/*
 * A348832  Positive numbers whose square starts and ends with exactly 444.
 * https://oeis.org/A348832
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   OEIS A348832 Positive integers whose squares start and end with
 *            exactly 444. The sequence is generated by scanning all integers
 *            ending with 38, 462, 538, or 962, squaring them and checking
 *            that the square begins with 444 and the fourth leading digit is
 *            not 4. The terms are produced in ascending o...
 * Range:     u8 none, u16 none, u32 none, u64 n <= 32, u128 n <= 32,
 *            big any n
 * Helpers:   digit_len, pow10, seq_mul
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/seq_mul.h"     /* seq_t seq_mul(seq_t, seq_t) */
#include "../utils/pow10.h"       /* seq_t pow10(idx_t) */
#include "../utils/digit_len.h"   /* int digit_len(seq_t) */

static seq_t *cache      = NULL;
static size_t cache_len  = 0;
static size_t cache_cap  = 0;
static seq_t next_scan   = (seq_t)1;   /* next integer to examine */

/* Ensure the cache can hold at least 'need' elements. */
static void ensure_cache_cap(size_t need)
{
    if (cache_cap < need) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 16;
        while (new_cap < need) new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) { exit(1); }
        cache = tmp;
        cache_cap = new_cap;
    }
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    /* n >= 1 by specification; guard against zero for safety */
    if (n == 0) return (seq_t)0;

    /* Produce terms until we have at least n of them. */
    while (cache_len < n) {
        /* Find the next candidate ending in one of the accepted residues. */
        seq_t cur = next_scan;
        while (true) {
            uint64_t r = (uint64_t)(cur % (seq_t)1000);
            if (r == 38 || r == 462 || r == 538 || r == 962) break;
            ++cur;
        }

        /* Compute its square. */
        seq_t sq = seq_mul(cur, cur);

        /* Must end with 444. */
        if (sq % (seq_t)1000 != 444) {
            cur = cur + 1;
            next_scan = cur;
            continue;
        }

        /* Determine the number of decimal digits of the square. */
        int D = digit_len(sq);
        if (D < 4) { /* too short to have four leading digits; skip */
            cur = cur + 1;
            next_scan = cur;
            continue;
        }

        /* Extract the first four leading digits of the square. */
        seq_t pow10_4 = pow10((idx_t)(D - 4));  /* 10^(D-4) */
        seq_t pref4   = sq / pow10_4;           /* first four digits   */
        seq_t pref3   = pref4 / 10;             /* first three digits  */

        /* Verify that the first three digits are 444 and the fourth is not 4. */
        if (pref3 == 444 && (pref4 % 10) != 4) {
            /* Store the valid term. */
            ensure_cache_cap(cache_len + 1);
            cache[cache_len++] = cur;
            if (cache_len >= n) {
                next_scan = cur + 1;
                return cache[n - 1];
            }
        }

        /* Advance to the next integer for examination. */
        cur = cur + 1;
        next_scan = cur;
    }

    return cache[n - 1];
}
